func gaugeArray(record export.Record, points []aggregation.Point) (*metricpb.Metric, error) {
	desc := record.Descriptor()
	labels := record.Labels()
	m := &metricpb.Metric{
		Name:        desc.Name(),
		Description: desc.Description(),
		Unit:        string(desc.Unit()),
	}

	pbLabels := stringKeyValues(labels.Iter())

	nk := desc.NumberKind()
	if nk != number.Int64Kind && nk != number.Float64Kind {
		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, nk)
	}

	pts := make([]*metricpb.NumberDataPoint, 0, len(points))
	for _, s := range points {
		pts = append(pts, numberDataPoint(pbLabels, record.StartTime(), record.EndTime(), nk, s.Number))
	}
	m.Data = &metricpb.Metric_Gauge{
		Gauge: &metricpb.Gauge{
			DataPoints: pts,
		},
	}

	return m, nil
}

func gaugePoint(record export.Record, num number.Number, start, end time.Time) (*metricpb.Metric, error) {
	desc := record.Descriptor()
	labels := record.Labels()

	m := &metricpb.Metric{
		Name:        desc.Name(),
		Description: desc.Description(),
		Unit:        string(desc.Unit()),
	}

	n := desc.NumberKind()
	if n != number.Int64Kind && n != number.Float64Kind {
		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
	}

	m.Data = &metricpb.Metric_Gauge{
		Gauge: &metricpb.Gauge{
			DataPoints: []*metricpb.NumberDataPoint{
				numberDataPoint(stringKeyValues(labels.Iter()), start, end, n, num),
			},
		},
	}

	return m, nil
}

func exportKindToTemporality(ek export.ExportKind) metricpb.AggregationTemporality {
	switch ek {
	case export.DeltaExportKind:
		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_DELTA
	case export.CumulativeExportKind:
		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_CUMULATIVE
	}
	return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_UNSPECIFIED
}

func sumPoint(record export.Record, num number.Number, start, end time.Time, ek export.ExportKind, monotonic bool) (*metricpb.Metric, error) {
	desc := record.Descriptor()
	labels := record.Labels()

	m := &metricpb.Metric{
		Name:        desc.Name(),
		Description: desc.Description(),
		Unit:        string(desc.Unit()),
	}

	n := desc.NumberKind()
	if n != number.Int64Kind && n != number.Float64Kind {
		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
	}

	m.Data = &metricpb.Metric_Sum{
		Sum: &metricpb.Sum{
			IsMonotonic:            monotonic,
			AggregationTemporality: exportKindToTemporality(ek),
			DataPoints: []*metricpb.NumberDataPoint{
				numberDataPoint(stringKeyValues(labels.Iter()), start, end, n, num),
			},
		},
	}

	return m, nil
}

// minMaxSumCountValue returns the values of the MinMaxSumCount Aggregator
// as discrete values.
func minMaxSumCountValues(a aggregation.MinMaxSumCount) (min, max, sum number.Number, count uint64, err error) {
	if min, err = a.Min(); err != nil {
		return
	}
	if max, err = a.Max(); err != nil {
		return
	}
	if sum, err = a.Sum(); err != nil {
		return
	}
	if count, err = a.Count(); err != nil {
		return
	}
	return
}

// minMaxSumCount transforms a MinMaxSumCount Aggregator into an OTLP Metric.
func minMaxSumCount(record export.Record, a aggregation.MinMaxSumCount) (*metricpb.Metric, error) {
	desc := record.Descriptor()
	labels := record.Labels()
	min, max, sum, count, err := minMaxSumCountValues(a)
	if err != nil {
		return nil, err
	}

	m := &metricpb.Metric{
		Name:        desc.Name(),
		Description: desc.Description(),
		Unit:        string(desc.Unit()),
	}

	buckets := []uint64{min.AsRaw(), max.AsRaw()}
	bounds := []float64{0.0, 100.0}

	n := desc.NumberKind()
	if n != number.Int64Kind && n != number.Float64Kind {
		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
	}
	m.Data = &metricpb.Metric_Histogram{
		Histogram: &metricpb.Histogram{
			DataPoints: []*metricpb.HistogramDataPoint{
				histogramDataPoint(stringKeyValues(labels.Iter()), record.StartTime(), record.EndTime(), uint64(count), sum.CoerceToFloat64(n), buckets, bounds),
			},
		},
	}
	return m, nil
}

func histogramValues(a aggregation.Histogram) (boundaries []float64, counts []uint64, err error) {
	var buckets aggregation.Buckets
	if buckets, err = a.Histogram(); err != nil {
		return
	}
	boundaries, counts = buckets.Boundaries, buckets.Counts
	if len(counts) != len(boundaries)+1 {
		err = ErrTransforming
		return
	}
	return
}

// histogram transforms a Histogram Aggregator into an OTLP Metric.
func histogramPoint(record export.Record, ek export.ExportKind, a aggregation.Histogram) (*metricpb.Metric, error) {
	desc := record.Descriptor()
	labels := record.Labels()
	boundaries, counts, err := histogramValues(a)
	if err != nil {
		return nil, err
	}

	count, err := a.Count()
	if err != nil {
		return nil, err
	}

	sum, err := a.Sum()
	if err != nil {
		return nil, err
	}

	m := &metricpb.Metric{
		Name:        desc.Name(),
		Description: desc.Description(),
		Unit:        string(desc.Unit()),
	}
	n := desc.NumberKind()
	if n != number.Int64Kind && n != number.Float64Kind {
		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
	}
	m.Data = &metricpb.Metric_Histogram{
		Histogram: &metricpb.Histogram{
			AggregationTemporality: exportKindToTemporality(ek),
			DataPoints: []*metricpb.HistogramDataPoint{
				histogramDataPoint(stringKeyValues(labels.Iter()), record.StartTime(), record.EndTime(), uint64(count), sum.CoerceToFloat64(n), counts, boundaries),
			},
		},
	}

	return m, nil
}

func numberDataPoint(labels []*commonpb.StringKeyValue, start, end time.Time, nk number.Kind, value number.Number) *metricpb.NumberDataPoint {
	dp := &metricpb.NumberDataPoint{
		Labels:            labels,
		StartTimeUnixNano: toNanos(start),
		TimeUnixNano:      toNanos(end),
	}
	switch nk {
