	case number.Float64Kind:
		dp.Value = &metricpb.NumberDataPoint_AsDouble{AsDouble: value.CoerceToFloat64(nk)}
	}
	return dp
}

func histogramDataPoint(labels []*commonpb.StringKeyValue, start, end time.Time, count uint64, sum float64, counts []uint64, bounds []float64) *metricpb.HistogramDataPoint {
	return &metricpb.HistogramDataPoint{
		Labels:            labels,
		StartTimeUnixNano: toNanos(start),
		TimeUnixNano:      toNanos(end),
		Count:             count,
		Sum:               sum,
		BucketCounts:      counts,
		ExplicitBounds:    bounds,
	}
}

